import{_ as l,o as a,c as e,aw as o}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"Выражения","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/js-regexp/main/use.md","filePath":"wiki/dev-commit/js/js-regexp/main/use.md"}'),t={name:"wiki/dev-commit/js/js-regexp/main/use.md"};function u(n,i,r,s,h,d){return a(),e("div",null,[...i[0]||(i[0]=[o('<h1 id="выражения" tabindex="-1">Выражения <a class="header-anchor" href="#выражения" aria-label="Permalink to &quot;Выражения&quot;">​</a></h1><h3 id="основное" tabindex="-1">Основное <a class="header-anchor" href="#основное" aria-label="Permalink to &quot;Основное&quot;">​</a></h3><ul><li>\\d - любая десятичная цифра</li><li>\\D - любой символ, кроме десятичной цифры</li><li>\\s - любой пробельный символ</li><li>\\S - любой непробельный символ</li><li>\\w - любой символ, образующий &quot;слово&quot;</li><li>\\W - любой символ, необразующий &quot;слово&quot;</li><li>\\b - граница слова</li><li>\\B - не граница слова</li><li>\\A - начало данных (независимо от многострочного режима)</li><li>\\Z - конец данных, либо позиция перед последним символом строки, в случае если это символ перевода строки (независимо от многострочного режима)</li><li>\\z - конец данных (независимо от многострочного режима)</li><li>[] - символьный класс</li><li>() - подмаска</li><li>| - разделитель альтернативных масок</li><li>{m,n} - квантификатор повтора: min m, max n раз</li><li>(?😃 - незахватывающая подмаска</li><li>(?=x) - положительное утверждение</li><li>(?!x) - отрицательное утверждение</li></ul><h3 id="expression-flag" tabindex="-1">Expression Flag <a class="header-anchor" href="#expression-flag" aria-label="Permalink to &quot;Expression Flag&quot;">​</a></h3><ul><li>//g - global (все совпадения)</li><li>//i - case insensitive (регистронезависимый поиск)</li><li>//m - multiline</li><li>//u - unicode</li><li>//y - sticky</li></ul><h3 id="символы" tabindex="-1">Символы <a class="header-anchor" href="#символы" aria-label="Permalink to &quot;Символы&quot;">​</a></h3><ul><li>\\f - символ разрыва страницы</li><li>\\t - символ табуляции</li><li>\\v - символ вертикальной табуляции</li><li>\\r - символ возврата каретки</li><li>\\n - символ перевода строки</li><li>\\xhh - символ с кодом hh</li><li>\\uhhhh - символ юникод с кодом hhhh</li></ul><h3 id="специальные-символы" tabindex="-1">Специальные символы <a class="header-anchor" href="#специальные-символы" aria-label="Permalink to &quot;Специальные символы&quot;">​</a></h3><ul><li>\\ - для обычных символов - делает их специальными. Например, выражение /s/ ищет просто символ &#39;s&#39;. А если поставить \\ перед s, то /\\s/ уже обозначает пробельный символ. И наоборот, если символ специальный, например <em>, то \\ сделает его просто обычным символом &quot;звездочка&quot;. Например, /a</em>/ ищет 0 или больше подряд идущих символов &#39;a&#39;. Чтобы найти а со звездочкой &#39;a*&#39; - поставим \\ перед спец. символом: /a*/.</li><li>^ - начало ввода (или линии, в многострочном режиме); отрицание в [],</li><li>$ - конец ввода (или линии, в многострочном режиме)</li><li><ul><li><ul><li>соответствует предыдущему символу повторенному 0 или более раз. Эквивалентно {0,}. Например, /bo*/ соответствует &#39;boooo&#39; в &quot;A ghost booooed&quot; и &#39;b&#39; в &quot;A bird warbled&quot;, но не в &quot;A goat grunted&quot;.</li></ul></li></ul></li><li><ul><li><ul><li>соответствует предыдущему символу повторенному 1 или более раз. Эквивалентно {1,}. Например, /a+/ соответствует &#39;a&#39; в &quot;candy&quot; и всем символам &#39;a&#39; в &quot;caaaaaaandy&quot;.</li></ul></li></ul></li><li>? - соответствует предыдущему символу повторенному 0 или 1 раз. Эквивалентно {0,1}.</li><li>. - (десятичная точка) соответствует любому символу кроме переноса строки. Например, /.n/ соответствует &#39;an&#39; и &#39;on&#39; в &quot;nay, an apple is on the tree&quot;, но не &#39;nay&#39;.</li></ul>',9)])])}const q=l(t,[["render",u]]);export{m as __pageData,q as default};
